def count_special_numbers(n, k):
    n = int(n, 2)
    dp = [[0] * (k + 1) for _ in range(31)]

    for i in range(1, 31):
        dp[i][1] = dp[i - 1][0]
        dp[i][0] = dp[i - 1][0] + dp[i - 1][i - 1]
        for j in range(2, k + 1):
            dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j]) % MOD

    def helper(x, ops):
        if x == 0:
            return 0
        if ops == 0:
            return dp[x.bit_length() - 1][x.bit_count()]

        res = 0
        bit = 1
        while x >= bit:
            if x & bit:
                res += helper(x ^ bit, ops - 1)
                res %= MOD
            bit <<= 1
        return res

    return helper(n, k)

