def count_special_numbers(n, k):
    def count_bits(x):
        return bin(x).count('1')

    def dp(n, k):
        memo = [[-1] * (k + 1) for _ in range(n + 1)]

        def dfs(num, remaining_operations):
            if num == 1:
                return 1
            if remaining_operations == 0 or num == 0:
                return 0
            if memo[num][remaining_operations] != -1:
                return memo[num][remaining_operations]

            total_ways = 0
            for i in range(1, num):
                if count_bits(i) <= count_bits(num):
                    total_ways += dfs(num - i, remaining_operations - 1)
                    total_ways %= MOD

            memo[num][remaining_operations] = total_ways
            return memo[num][remaining_operations]

        return dfs(n, k)

    return dp(int(n, 2), k)

