def count_special_numbers(n: int, k: int) -> int:
    dp = [[0] * (k + 1) for _ in range(1001)]

    for i in range(k + 1):
        dp[0][i] = 1

    for i in range(1, 1001):
        dp[i][0] = 1

    for i in range(1, 1001):
        for j in range(1, k + 1):
            dp[i][j] = dp[i-1][j] + dp[i//2][j-(i&1)]

    bin_n = bin(n)[2:]
    length = len(bin_n)

    def count_specials(length, remaining_ops, prefix):
        if remaining_ops == 0:
            return 1
        if remaining_ops > length or length == 0:
            return 0

        total = 0
        for digit in [0, 1]:
            if prefix == '1':
                next_prefix = str(digit)
            else:
                next_prefix = ''

            total += count_specials(length - 1, remaining_ops - digit, next_prefix)

        return total % MOD

    result = count_specials(length, k, '')

    return result

