def count_special_numbers(n, k):
    dp = [[0] * (k + 1) for _ in range(len(bin(n)) - 2)]

    for i in range(1, len(dp)):
        dp[i][1] = dp[i-1][1]
        dp[i][0] = dp[i-1][0]

    for i in range(1, len(dp)):
        for j in range(2, min(i+1, k+1)):
            dp[i][j] = (dp[i-1][j] + dp[i-1][j-1]) % MOD

    count = 0
    current_count = 0
    for i in range(len(dp) - 1, -1, -1):
        if bin(n)[i+2] == '1':
            current_count += dp[i][k]
            count += current_count

    return count

